// Shared presentation for short metadata and primary/secondary place names.
export function divider(doc=document){const node=doc.createElement('span');node.className='meta-divider';node.setAttribute('aria-hidden','true');node.textContent=' ';return node;}
export function metadata(container,parts){const doc=container.ownerDocument||document;container.replaceChildren();parts.filter(v=>v!==undefined&&v!==null&&v!=='').forEach((value,i)=>{if(i)container.append(divider(doc));container.append(typeof value==='object'?value:doc.createTextNode(String(value)));});return container;}
export function splitMetadata(container){const doc=container.ownerDocument||document;for(const node of [...(container.childNodes||[])])if(node.nodeType===3&&node.textContent.includes(' · ')){const parts=node.textContent.split(' · '),nodes=[];parts.forEach((text,i)=>{if(i)nodes.push(divider(doc));if(text)nodes.push(doc.createTextNode(text));});node.replaceWith(...nodes);}return container;}
export function nameParts(container,primary,secondary){const doc=container.ownerDocument||document;container.replaceChildren();const main=doc.createElement('span');main.className='name-primary';main.textContent=primary||'';container.append(main);if(secondary&&secondary!==primary){container.append(doc.createTextNode(' '));const detail=doc.createElement('span');detail.className='name-secondary';detail.textContent=secondary.replaceAll(' · ',' — ');container.append(detail);}return container;}
export function bilingualText(container,text){const [main,...rest]=String(text||'').split(' · ');return nameParts(container,main,rest.join(' — '));}
